40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        validateRequiredFields(ownerFieldsDto);
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        this.clinicService.saveOwner(owner);
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        headers.setLocation(UriComponentsBuilder.newInstance()
110	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
111	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
112	    }
113	
114	    /**
115	     * Rejects an owner whose required fields are missing (null) or blank (empty or whitespace only).
116	     * Bean Validation already covers the {@code null} case and the fields constrained by a pattern,
117	     * but a whitespace-only {@code address} or {@code city} satisfies the generated {@code @Size}
118	     * constraint, so they are checked explicitly here. Every offending field name is collected so the
119	     * client receives the complete list at once.
120	     *
121	     * @param ownerFieldsDto the submitted owner fields
122	     * @throws InvalidRequestException if one or more required fields are missing or blank
123	     */
124	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
125	        List<String> errors = new ArrayList<>();
126	        if (isBlank(ownerFieldsDto.getFirstName())) {
127	            errors.add("firstName");
128	        }
129	        if (isBlank(ownerFieldsDto.getLastName())) {
130	            errors.add("lastName");
131	        }
132	        if (isBlank(ownerFieldsDto.getAddress())) {
133	            errors.add("address");
134	        }
135	        if (isBlank(ownerFieldsDto.getCity())) {
136	            errors.add("city");
137	        }
138	        if (isBlank(ownerFieldsDto.getTelephone())) {
139	            errors.add("telephone");
140	        }
141	        if (!errors.isEmpty()) {
142	            throw new InvalidRequestException(errors);
143	        }
144	    }
145	
146	    private boolean isBlank(String value) {
147	        return value == null || value.isBlank();
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        currentOwner.setAddress(ownerFieldsDto.getAddress());
158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        HttpHeaders headers = new HttpHeaders();
186	        Pet pet = petMapper.toPet(petFieldsDto);
187	        owner.setId(ownerId);
188	        pet.setOwner(owner);
189	        pet.getType().setName(null);
190	        this.clinicService.savePet(pet);
191	        PetDto petDto = petMapper.toPetDto(pet);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
193	            .buildAndExpand(pet.getId()).toUri());
194	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
